generic.example:
func First[T any](items []T) (T, bool) {
  if len(items) == 0 {
    var zero T
    return zero, false
  }
  return items[0], true
}

any.example:
func PrintAll[T any](items []T) {
  for _, item := range items {
    fmt.Println(item)
  }
}

comparable.example:
func HasKey[K comparable, V any](m map[K]V, k K) bool {
  _, ok := m[k]
  return ok
}

Adder.example:
type Adder[A Adder[A]] interface {
  Add(A) A
}

func Sum[A Adder[A]](x, y A) A {
  return x.Add(y)
}
